package com.huy.enterprise.alert; import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.*; import com.huy.enterprise.risk.RiskEventRepository; import com.huy.enterprise.user.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime; import java.util.*; @Service @RequiredArgsConstructor public class AlertService {private final AlertRepository repo;private final UserRepository users;private final RiskEventRepository risks; Alert entity(UUID id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Alert not found: "+id));}List<AlertResponse> all(){return repo.findAll().stream().map(AlertResponse::from).toList();}AlertResponse get(UUID id){return AlertResponse.from(entity(id));}@Transactional AlertResponse create(AlertRequest x){var a=new Alert();a.setTitle(x.title());a.setMessage(x.message());a.setAlertType(x.alertType());a.setPriority(x.priority()==null?AlertPriority.MEDIUM:x.priority());a.setRecipientUser(x.recipientUserId()==null?null:users.findById(x.recipientUserId()).orElseThrow(()->new ResourceNotFoundException("User not found: "+x.recipientUserId())));a.setRiskEvent(x.riskEventId()==null?null:risks.findById(x.riskEventId()).orElseThrow(()->new ResourceNotFoundException("Risk event not found: "+x.riskEventId())));return AlertResponse.from(repo.save(a));}@Transactional AlertResponse status(UUID id,AlertStatusRequest x){var a=entity(id);var from=a.getStatus();var to=x.status();if(from==AlertStatus.RESOLVED||from==AlertStatus.READ&&to==AlertStatus.NEW||from==AlertStatus.NEW&&to==AlertStatus.NEW||from==AlertStatus.READ&&to==AlertStatus.READ)throw new BusinessException("Invalid alert status transition: "+from+" -> "+to);a.setStatus(to);a.setResolvedAt(to==AlertStatus.RESOLVED?OffsetDateTime.now():null);return AlertResponse.from(repo.save(a));}}
